\set ON_ERROR_STOP on
\set QUIET on
set client_min_messages = notice;

-- ---- owner adds products (as the owner login) ----
set role authenticated; select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
insert into public.products (name, category, price, stock) values ('Tea 950g', 'grocery', 1000, 10), ('Rice 5kg', 'grocery', 2000, 3), ('Sold Out Soap', 'bakery', 100, 0);
select test.ok((select count(*) from public.products) = 3, 'owner can add products');

-- ---- another logged-in user (not the owner) is blocked ----
select set_config('request.jwt.claims', '{"email":"attacker@evil.test"}', false);
select test.ok(test.fails($$insert into public.products (name, category, price, stock) values ('Fake','x',1,1)$$), 'non-owner login cannot add products');
update public.products set price = 1;
select test.ok((select min(price) from public.products) = 100, 'non-owner login cannot change prices (rows untouched)');

-- ---- customers (anon) ----
reset role; set role anon; select set_config('request.jwt.claims', '', false);
select test.ok((select count(*) from public.products) = 3, 'customers can read products');
select test.ok(test.fails($$insert into public.products (name, category, price, stock) values ('Fake','x',1,1)$$), 'customers cannot add products');
update public.products set price = 1, stock = 999;
select test.ok((select min(price) from public.products) = 100 and (select max(stock) from public.products) = 10, 'customers cannot change price or stock');
select test.ok((select count(*) from public.orders) = 0, 'customers cannot read orders');
select test.ok(test.fails($$insert into public.orders (id, customer, items, subtotal, total) values ('X','{}','[]',0,0)$$), 'customers cannot insert orders directly');
select test.ok((select count(*) from public.coupons) = 3, 'customers can read coupons');
select test.ok(test.fails($$insert into public.coupons (code, type, value) values ('FREE100','percent',90)$$), 'customers cannot create coupons');
select test.ok(test.fails($$delete from public.coupons$$) or (select count(*) from public.coupons) = 3, 'customers cannot delete coupons');

-- ---- place_order: server decides prices, stock, discount, delivery ----
create temp table res (j jsonb);  -- customers' temp table, role anon owns it
insert into res select public.place_order('{"customer":{"name":"Ayesha Khan","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III","notes":"ring bell"},
  "items":[{"id":1,"qty":2,"price":1}], "coupon":null}'::jsonb);
select test.ok((select (j->>'subtotal')::numeric from res) = 2000, 'server uses real product price (client price 1 ignored)');
select test.ok((select (j->>'deliveryFee')::numeric from res) = 199 and (select (j->>'total')::numeric from res) = 2199, 'delivery Rs. 199 under Rs. 3000');
select test.ok((select j->>'id' from res) ~ '^AHS-[0-9]{6}-[0-9]{4}$', 'order number generated by server');
reset role; select test.ok((select stock from public.products where id = 1) = 8, 'stock reduced after order (10 -> 8)');
set role anon;

delete from res;
insert into res select public.place_order('{"customer":{"name":"Bilal Raza","phone":"+923217654321","city":"Karachi","address":"Flat 4B, Clifton Block 5"},
  "items":[{"id":1,"qty":3}], "coupon":"welcome10"}'::jsonb);
select test.ok((select (j->>'discount')::numeric from res) = 300 and (select (j->>'deliveryFee')::numeric from res) = 199 and (select (j->>'total')::numeric from res) = 2899, 'percent coupon recalculated on server (lower-case code accepted)');
delete from res;
insert into res select public.place_order('{"customer":{"name":"Sana Malik","phone":"0333-9988776","city":"Islamabad","address":"Street 9, F-10/3"},
  "items":[{"id":2,"qty":2}], "coupon":"FREESHIP"}'::jsonb);
select test.ok((select (j->>'deliveryFee')::numeric from res) = 0 and (select (j->>'total')::numeric from res) = 4000, 'free-delivery coupon');
reset role; select test.ok((select stock from public.products where id = 2) = 1, 'stock of second product reduced (3 -> 1)'); set role anon;

select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Bad Phone","phone":"12345","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":1}]}'::jsonb)$$), 'bad phone number rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Al","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":1}]}'::jsonb)$$), 'short name rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"short"},"items":[{"id":1,"qty":1}]}'::jsonb)$$), 'short address rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[]}'::jsonb)$$), 'empty cart rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":50}]}'::jsonb)$$), 'more than available stock rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":3,"qty":1}]}'::jsonb)$$), 'out-of-stock item rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":999,"qty":1}]}'::jsonb)$$), 'unknown product rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":-1}]}'::jsonb)$$), 'negative quantity rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":1}],"coupon":"MADEUP"}'::jsonb)$$), 'unknown coupon rejected');
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":1}],"coupon":"SAVE200"}'::jsonb)$$), 'coupon below its minimum order rejected');
reset role; select test.ok((select stock from public.products where id = 1) = 5 and (select stock from public.products where id = 2) = 1, 'failed orders did not change stock'); set role anon;
select test.ok((select count(*) from public.orders) = 0, 'customers still cannot read orders');

-- duplicate lines of the same product cannot exceed stock
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":2,"qty":1},{"id":2,"qty":1}]}'::jsonb)$$), 'duplicate lines cannot bypass stock');
reset role; select test.ok((select stock from public.products where id = 2) = 1, 'stock unchanged after rejected duplicate-line order');

-- ---- owner manages orders ----
set role authenticated; select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
select test.ok((select count(*) from public.orders) = 3, 'owner can read all orders');
select test.ok(test.fails($$update public.orders set status = 'Delivered' where status = 'Pending'$$), 'Pending -> Delivered rejected');
select test.ok(test.fails($$update public.orders set status = 'Shipped' where status = 'Pending'$$), 'unknown status rejected');
update public.orders set status = 'Confirmed' where customer->>'name' = 'Ayesha Khan';
select test.ok((select status from public.orders where customer->>'name' = 'Ayesha Khan') = 'Confirmed', 'Pending -> Confirmed allowed');
update public.orders set total = 1, items = '[]', discount = 99999 where customer->>'name' = 'Ayesha Khan';
select test.ok((select total from public.orders where customer->>'name' = 'Ayesha Khan') = 2199 and jsonb_array_length((select items from public.orders where customer->>'name' = 'Ayesha Khan')) = 1, 'money and items of an order cannot be edited');
update public.orders set status = 'Cancelled' where customer->>'name' = 'Ayesha Khan';
reset role; select test.ok((select stock from public.products where id = 1) = 7, 'cancel restores stock once (5 -> 7)');
set role authenticated; select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
select test.ok(test.fails($$update public.orders set status = 'Confirmed' where customer->>'name' = 'Ayesha Khan'$$), 'Cancelled order cannot be reopened');
update public.orders set status = 'Cancelled', follow_up_sent = true where customer->>'name' = 'Ayesha Khan';
reset role; select test.ok((select stock from public.products where id = 1) = 7, 'stock NOT restored a second time');
set role authenticated; select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
update public.orders set status = 'Confirmed' where customer->>'name' = 'Bilal Raza';
update public.orders set status = 'Processing' where customer->>'name' = 'Bilal Raza';
select test.ok(test.fails($$update public.orders set status = 'Delivered' where customer->>'name' = 'Bilal Raza'$$), 'Processing -> Delivered rejected (must go out for delivery first)');
update public.orders set status = 'Out for Delivery' where customer->>'name' = 'Bilal Raza';
update public.orders set status = 'Delivered' where customer->>'name' = 'Bilal Raza';
select test.ok((select status from public.orders where customer->>'name' = 'Bilal Raza') = 'Delivered', 'Pending -> Confirmed -> Processing -> Out for Delivery -> Delivered');
select test.ok(test.fails($$update public.orders set status = 'Cancelled' where customer->>'name' = 'Bilal Raza'$$), 'Delivered order cannot be cancelled');

-- ---- customers cannot touch orders, owner contact is protected ----
reset role; set role anon; select set_config('request.jwt.claims', '', false);
update public.orders set status = 'Delivered', total = 1;
reset role; select test.ok((select count(*) from public.orders where total = 1) = 0, 'customers cannot update orders');
set role authenticated; select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
insert into public.owner_contact (id, phone, email) values (1, '0300-1112223', 'owner@shop.test');
reset role; set role anon; select set_config('request.jwt.claims', '', false);
select test.ok((select email from public.owner_contact where id = 1) = 'owner@shop.test', 'store can read owner contact');
select test.ok(test.fails($$insert into public.owner_contact (id, phone, email) values (1,'x','y') on conflict (id) do update set email = 'hacked@evil.test'$$), 'customers cannot overwrite owner contact');
delete from public.owner_contact;
select test.ok((select count(*) from public.owner_contact) = 1, 'customers cannot delete owner contact');
reset role; set role authenticated; select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
delete from public.owner_contact where id = 1;
select test.ok((select count(*) from public.owner_contact) = 0, 'owner Reset deletes phone and email');
reset role;

-- ---- categories ----
reset role; set role anon; select set_config('request.jwt.claims', '', false);
select test.ok((select count(*) from public.categories) = 12, 'customers can read the 12 categories');
select test.ok(test.fails($$insert into public.categories (slug, name) values ('hacked','Hacked')$$), 'customers cannot add categories');
update public.categories set name = 'Hacked name';
delete from public.categories;
reset role; select test.ok((select count(*) from public.categories) = 12 and (select count(*) from public.categories where name = 'Hacked name') = 0, 'customers cannot rename or delete categories');
set role authenticated; select set_config('request.jwt.claims', '{"email":"attacker@evil.test"}', false);
select test.ok(test.fails($$insert into public.categories (slug, name) values ('hacked','Hacked')$$), 'non-owner login cannot add categories');
select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
insert into public.categories (slug, name, short, sort_order) values ('toys', 'Toys & Games', 'Toys', 20);
select test.ok((select count(*) from public.categories) = 13, 'owner can add a category');
select test.ok(test.fails($$insert into public.categories (slug, name) values ('toys-2','toys & games')$$), 'duplicate category name rejected (case-insensitive)');
select test.ok(test.fails($$insert into public.categories (slug, name) values ('toys','Another')$$), 'duplicate category slug rejected');
select test.ok(test.fails($$insert into public.categories (slug, name) values ('Bad Slug!','Bad')$$), 'invalid slug rejected');
select test.ok(test.fails($$insert into public.products (name, category, price, stock) values ('Orphan', 'no-such-category', 10, 1)$$), 'product with unknown category rejected');
select test.ok(test.fails($$delete from public.categories where slug = 'grocery'$$), 'category that still has products cannot be deleted');
update public.categories set name = 'Toys and Games' where slug = 'toys';
select test.ok((select name from public.categories where slug = 'toys') = 'Toys and Games', 'owner can edit a category');
delete from public.categories where slug = 'toys';
select test.ok((select count(*) from public.categories) = 12, 'owner can delete an empty category');

-- ---- coupons: expiry, usage limit, usage counted, restored on cancel ----
insert into public.coupons (code, type, value, expires_at) values ('OLDDEAL', 'percent', 10, now() - interval '1 day');
insert into public.coupons (code, type, value, usage_limit) values ('ONCEONLY', 'flat', 100, 1);
select test.ok(test.fails($$insert into public.coupons (code, type, value, usage_limit) values ('BADLIM','flat',1,0)$$), 'usage limit must be positive');
reset role; set role anon; select set_config('request.jwt.claims', '', false);
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Valid Name","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":1}],"coupon":"OLDDEAL"}'::jsonb)$$), 'expired coupon rejected');
reset role; select test.ok((select stock from public.products where id = 1) = 7, 'rejected expired-coupon order did not touch stock'); set role anon;
delete from res;
insert into res select public.place_order('{"customer":{"name":"Coupon One","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":1}],"coupon":"ONCEONLY"}'::jsonb);
select test.ok((select (j->>'discount')::numeric from res) = 100, 'limited coupon works the first time');
reset role; select test.ok((select used_count from public.coupons where code = 'ONCEONLY') = 1, 'coupon use is counted'); set role anon;
select test.ok(test.fails($$select public.place_order('{"customer":{"name":"Coupon Two","phone":"0300-1234567","city":"Lahore","address":"House 12, Gulberg III"},"items":[{"id":1,"qty":1}],"coupon":"ONCEONLY"}'::jsonb)$$), 'coupon over its usage limit rejected');
reset role; select test.ok((select stock from public.products where id = 1) = 6, 'rejected over-limit order did not touch stock');
set role authenticated; select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
update public.orders set status = 'Confirmed' where customer->>'name' = 'Coupon One';
update public.orders set status = 'Cancelled' where customer->>'name' = 'Coupon One';
update public.orders set status = 'Cancelled' where customer->>'name' = 'Coupon One';
reset role; select test.ok((select used_count from public.coupons where code = 'ONCEONLY') = 0, 'cancelling gives the coupon use back exactly once');
select test.ok((select stock from public.products where id = 1) = 7, 'cancelling the coupon order restored its stock once');
set role anon; select set_config('request.jwt.claims', '', false);
update public.coupons set used_count = 0, usage_limit = 9999, active = true;
reset role; select test.ok((select usage_limit from public.coupons where code = 'ONCEONLY') = 1, 'customers cannot edit coupon limits');

-- ---- newsletter ----
set role anon; select set_config('request.jwt.claims', '', false);
select test.ok(public.subscribe_newsletter('  Fan@Example.COM ') = 'subscribed', 'newsletter: new subscriber saved');
select test.ok(public.subscribe_newsletter('fan@example.com') = 'already', 'newsletter: duplicate recognised (case-insensitive)');
select test.ok(test.fails($$select public.subscribe_newsletter('not-an-email')$$), 'newsletter: invalid email rejected');
select test.ok(test.fails($$select public.subscribe_newsletter('')$$), 'newsletter: empty email rejected');
select test.ok((select count(*) from public.newsletter_subscribers) = 0, 'customers cannot read the subscriber list');
select test.ok(test.fails($$insert into public.newsletter_subscribers (email) values ('direct@example.com')$$), 'customers cannot insert subscribers directly');
reset role; select test.ok((select count(*) from public.newsletter_subscribers) = 1, 'exactly one subscriber stored');
set role authenticated; select set_config('request.jwt.claims', '{"email":"owner@shop.test"}', false);
select test.ok((select count(*) from public.newsletter_subscribers) = 1, 'owner can read the subscriber list');
reset role;

select 'ALL DATABASE TESTS PASSED' as result;
